-- Gold Class Bar as configured on the live app (catalogue only: areas, categories, products, order,
-- subheadings). For testing the category update and the collection/finish screens. Test database only.
do $$
declare dept uuid := (select id from departments where name = 'Gold Class Bar');
begin
  update check_areas set active = false, name = name || ' (old)' where department_id = dept;
  update products set status = 'archived', name = name || ' (old)' where department_id = dept;
  update storage_locations set sort_order = 1 where lower(name) = lower('Alcohol storeroom');
  update storage_locations set sort_order = 2 where lower(name) = lower('Walk in fridge(Downstairs)');
  update storage_locations set sort_order = 3 where lower(name) = lower('Walk in freezer(Downstairs)');
  update storage_locations set sort_order = 4 where lower(name) = lower('Dry storage');
  update storage_locations set sort_order = 5 where lower(name) = lower('Candy Bar BOH');
end $$;
